/**
 * POST /api/radio/request — 热线点歌。
 *
 * 入参 { text: "来一首欢快的爵士" }。解析（词典归一化）→ 本地曲库关联打分
 * → 立即开播最贴近的一首，返回可解释结果（匹配到的词、选曲原因、候补）。
 * 解析出的 unknownTerms 会原样返回 —— 对话 agent 据此追问用户并调
 * /api/radio/lexicon 教学，新词下次就是母语。
 */
import { playRequest } from '@/server/radio/request';
import { announce } from '@/server/radio/station';
import { ok, fail } from '@/server/http';

export async function POST(request: Request) {
	let body: { text?: unknown };
	try {
		body = await request.json();
	} catch {
		return fail('Invalid JSON body', 400);
	}
	const text = typeof body.text === 'string' ? body.text.trim() : '';
	if (!text) {
		return fail('text is required', 400);
	}
	try {
		const result = await playRequest(text);
		if (result.played) {
			announce(`收到点播「${text}」，上 ${result.played.artist} 的《${result.played.title}》`);
		}
		return ok(result);
	} catch (err) {
		return fail(err instanceof Error ? err.message : String(err), 500);
	}
}
