/**
 * radio/request — 热线点歌：把一句自然语言落成本地曲库里的一首歌。
 *
 * 「来一首欢快的爵士」的处理流水线：
 *   parseQuery（词典归一化：欢快→happy/upbeat/energetic，爵士→jazz）
 *     → 全曲库关联打分（标签匹配 + 长期记忆 + 新鲜度，全部本地信号）
 *     → 取第一名开播 → 口播确认 → 记忆回流
 *
 * 关联打分刻意透明：返回 reasons，前端/对话里都能解释「为什么是这首」。
 * 解析出 unknownTerms 时照常播最接近的，并把生词带给调用方（agent 据此
 * 追问教学 → teachTerm 写入 learned 词典，下次这个词就是母语了）。
 */
import type { Song } from '@/server/library';
import { getSnapshot, playTrackById, ensureQueue } from '@/server/player/state';
import { fusedTags, getAllTrackStats, getTrackStat } from './memory';
import { parseQuery, type ParsedQuery } from './lexicon';

export type RequestResult = {
	played: Song | null;
	parsed: ParsedQuery;
	reasons: string[];
	alternatives: { song: Song; reasons: string[] }[];
};

/** 点播关联打分：标签匹配为主，记忆与新鲜度微调。 */
async function scoreByQuery(
	songs: Song[],
	parsed: ParsedQuery,
): Promise<{ song: Song; reasons: string[] }[]> {
	const nowMs = Date.now();
	const stats = new Map(getAllTrackStats().map((s) => [s.track_id, s]));

	const scored = songs.map((song) => {
		const stat = stats.get(song.id) ?? getTrackStat(song.id);
		const reasons: string[] = [];
		let score = 0.3;

		// 融合标签视图（user/llm 取代 ID3 原字段，不是并集——见 fusedTags 注释）
		const { genres: songGenres, moods: songMoods } = fusedTags(song);

		// 1. 情绪标签匹配（用户的主观词）
		const moodIdx = parsed.moods.findIndex((m) => songMoods.includes(m));
		if (parsed.moods.length > 0 && moodIdx >= 0) {
			score += moodIdx === 0 ? 0.6 : 0.3;
			reasons.push(`情绪相符(${songMoods[moodIdx]})`);
		}
		// 2. 风格标签匹配（用户的专业词）
		const genreIdx = parsed.genres.findIndex((g) => songGenres.includes(g));
		if (parsed.genres.length > 0 && genreIdx >= 0) {
			score += genreIdx === 0 ? 0.5 : 0.25;
			reasons.push(`风格相符(${songGenres[genreIdx]})`);
		}
		// 3. 长期记忆：常听微加成，频繁跳过压下去
		if (stat.play_count > 0) {
			score += Math.min(0.15, 0.05 * Math.log2(1 + stat.play_count));
		}
		if (stat.skip_count > 0) {
			score -= 0.2 * (stat.skip_count / Math.max(1, stat.play_count + stat.skip_count));
			reasons.push(`你跳过它 ${stat.skip_count} 次`);
		}
		// 4. 新鲜度：刚在电台播过的略降权（点播场景宽松处理）
		if (stat.last_played_at && nowMs - new Date(stat.last_played_at).getTime() < 45 * 60_000) {
			score -= 0.15;
			reasons.push('刚播过不久');
		}
		if (reasons.length === 0) reasons.push(`综合评分 ${score.toFixed(2)}`);
		return { song, score: Math.round(score * 1000) / 1000, reasons };
	});

	scored.sort((a, b) => b.score - a.score);
	return scored;
}

/**
 * 处理一句点播：解析 → 关联 → 开播（接管下一首）→ 返回可解释结果。
 * radio 开着时：插播（放到当前曲目之后立即切播）；关着时：直接单曲开播。
 */
export async function playRequest(text: string): Promise<RequestResult> {
	const parsed = parseQuery(text);
	const { getSongs } = await import('@/server/library');
	const songs = await getSongs();
	if (songs.length === 0) {
		return { played: null, parsed, reasons: ['曲库为空'], alternatives: [] };
	}

	const ranked = await scoreByQuery(songs, parsed);
	const top = ranked[0];

	// 让目标成为「当前曲目之后的下一首」并立即切播：
	// 队列里已有 → 直接切；没有 → 以它开头重建队列（其余保序跟在后面）。
	const snap = getSnapshot();
	const { findSongById } = await import('@/server/library');
	const topSong = (await findSongById(top.song.id)) ?? top.song;
	if (!snap.queue.some((q) => q.id === topSong.id)) {
		const others = await Promise.all(
			snap.queue.filter((q) => q.id !== topSong.id).map((q) => findSongById(q.id)),
		);
		const othersOk = others.filter((s): s is Song => Boolean(s));
		ensureQueue([topSong, ...othersOk]);
	}
	playTrackById(topSong.id);

	return {
		played: topSong,
		parsed,
		reasons: top.reasons,
		alternatives: ranked.slice(1, 4).map((r) => ({ song: r.song, reasons: r.reasons })),
	};
}
